-- Migration 493: AA-1142 follow-up (S293) — the external checks of the Ecosystem status page run on the CIS worker:
-- its sources, run interval, time limit per step and target list as settings.
--
-- Why. The root repo workflow External checks (GitHub Actions, cron every 15 minutes) had 0 scheduled runs on its
-- first day and the other root crons start up to 10 hours late, so the page's external card was never fresh. The code
-- PR adds the job kind ops_external_check (the AA-1178 monitoring lane, $0, no new AWS service): the CIS worker runs
-- the same checks (DNS, verified TLS handshake and certificate end date, one GET of the health path without following
-- redirects) from its internet egress, and the GitHub workflow stays as an optional second vantage point. Every value
-- that steers it is a setting (tech lead S279: a threshold, limit or list of targets is maker-checker and audited,
-- never a code literal or an env var), and the target list is editable in admin instead of hard-coded hosts.
--
-- What:
--   1. Four rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), app cis, area "ops", scope platform, impact medium,
--      maker-checker, no evidence, no env override, enforced (shared/ops_external_settings.py names every key, the
--      settings-lint reader check):
--        cis.ops.external_check_sources        list of worker | github, default both
--        cis.ops.external_check_interval_min   int minutes 5-60, default 15
--        cis.ops.external_check_timeout_s      int seconds 2-30, default 10 (the root workflow's value)
--        cis.ops.external_check_targets        json list of {id, app, host, mode, path, expect}, default = the eight
--                                              public Dev hosts of root tools/ops/external_checks.json
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 493.
--
-- Behaviour on apply. None for running code: no value row is seeded and the code on main reads none of the keys. After
-- the code PR the api queues the worker's checks and the sampler copies the GitHub runs with these defaults.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR (with CIS 492), applied on Dev by Infra Migration Apply when the job tables are idle (ADR
-- 0017a), then the code PR. No readiness raise for 493: the reader serves the compiled defaults while the rows are
-- missing. DM-6.1: no personal data (public host names). DM-7.1: no new table.
--
-- Number. Owner main max + 1 after CIS 492 of the same batch (492-493, one migration-only PR). If the owner main max
-- + 1 differs at merge, renumber: git grep '493_' and "'493'" (this file, tests/integration/
-- test_aa1142_migration_492_493.py, compiled_defaults.json's _generated line, docs/implementation-notes/AA-1142.md).
--
-- Locks. One INSERT ... ON CONFLICT of four rows (the definition guard trigger allows the file's role, cis_owner).
-- lock_timeout 5s. Re-runnable: ON CONFLICT DO NOTHING keeps a row an earlier run wrote.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the four keys' value rows first, then the
-- keys.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.ops.external_check_sources", "app": "cis", "area": "ops", "label": "External checks: sources the status page counts", "description": "Where the external checks of the Ecosystem status page (/admin/overview, External checks card) are measured from: worker (the CIS worker's monitoring job ops_external_check, services/jobs/ops_external_check_job.py, every cis.ops.external_check_interval_min minutes from the worker's internet egress) and github (the root repo workflow External checks on GitHub Actions, copied by the 5-minute status sampler; GitHub may start it hours late). A source left out is not run (worker) or not copied (github), and the page ignores its rows. The feed counts as stopped only when every listed source is older than cis.ops.status_stale_factor x its own interval. Default both.", "value_type": "list", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["worker", "github"], "default_value": ["worker", "github"], "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "Which vantage points run the outside checks of the public hosts: the CIS worker, GitHub Actions, or both.", "raise": "Listing both: two independent vantage points; the page stays fresh while one of them is late or down.", "lower": "Removing one: that source stops (worker) or is no longer copied (github) and its strips leave the page; an empty list turns the external checks off.", "when": "Remove github if its schedule keeps running hours late and the grey strips distract; remove worker only to stop the checks from AWS.", "example": "With the default, every host shows a worker strip every 15 minutes and a GitHub strip whenever the workflow ran."}, "vi": {"what": "Những điểm đo chạy kiểm tra từ bên ngoài tới các host công khai: worker của CIS, GitHub Actions, hoặc cả hai.", "raise": "Để cả hai: hai điểm đo độc lập; trang vẫn tươi khi một nguồn bị trễ hoặc hỏng.", "lower": "Bỏ một nguồn: nguồn đó ngừng chạy (worker) hoặc không còn được chép (github) và dải của nó rời trang; danh sách rỗng là tắt kiểm tra bên ngoài.", "when": "Bỏ github nếu lịch của nó liên tục trễ hàng giờ và dải xám gây nhiễu; chỉ bỏ worker khi muốn dừng kiểm tra từ AWS.", "example": "Với mặc định, mỗi host có một dải worker mỗi 15 phút và một dải GitHub mỗi khi workflow chạy."}}},
{"key": "cis.ops.external_check_interval_min", "app": "cis", "area": "ops", "label": "External checks: worker run every (minutes)", "description": "How often the CIS worker runs the external checks (job kind ops_external_check, monitoring lane, queued by the api's ops metrics sampler once per bucket of this many minutes, aligned to the UTC hour). Each run checks every target of cis.ops.external_check_targets: DNS, a verified TLS handshake and the certificate's end date, one GET of the health path without following redirects. The status page judges the worker strip stale after cis.ops.status_stale_factor x this interval. A run that starts more than one interval late writes nothing (the next bucket is the retry). Default 15.", "value_type": "int", "unit": "minutes", "min_value": 5, "max_value": 60, "allowed_values": null, "default_value": 15, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many minutes apart the CIS worker checks the public hosts from outside.", "raise": "Fewer runs and rows (about 8 rows a run); an outage of a public host is seen later.", "lower": "A DNS, certificate or health failure shows sooner, at the price of more rows and requests to the hosts.", "when": "Lower it during an incident on a public host; raise it if the table grows too fast.", "example": "With the default 15, a host that stops answering at 10:02 is on the page as down by about 10:15."}, "vi": {"what": "Số phút giữa hai lần worker của CIS kiểm tra các host công khai từ bên ngoài.", "raise": "Ít lượt và ít dòng hơn (khoảng 8 dòng mỗi lượt); host công khai hỏng sẽ được thấy muộn hơn.", "lower": "Lỗi DNS, chứng chỉ hay đường health hiện ra sớm hơn, đổi lại nhiều dòng và nhiều yêu cầu tới host hơn.", "when": "Giảm khi đang có sự cố ở một host công khai; tăng nếu bảng phình quá nhanh.", "example": "Với mặc định 15, một host ngừng trả lời lúc 10:02 sẽ hiện là hỏng trên trang vào khoảng 10:15."}}},
{"key": "cis.ops.external_check_timeout_s", "app": "cis", "area": "ops", "label": "External checks: time limit per step (seconds)", "description": "The longest the CIS worker's external checks (job kind ops_external_check) wait for one step of one target: the TCP connection and TLS handshake, and the GET of the health path. A step that takes longer fails: the target is down for that run (no connection) or its request failed. Targets are checked in parallel, so one run lasts at most about three times this value. Default 10, the value of the root repo workflow (tools/ops/external_checks.py).", "value_type": "int", "unit": "seconds", "min_value": 2, "max_value": 30, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How long the worker waits for a public host to connect, finish the TLS handshake or answer its health path before calling it failed.", "raise": "A slow host is less often reported down, but a hung host holds the run longer.", "lower": "A slow answer counts as a failure sooner; too low and a busy but working host reads as down.", "when": "Raise it if a host is reported down while it answers in a browser; keep the default otherwise.", "example": "With the default 10, a health path that answers after 12 seconds is reported as a failed request."}, "vi": {"what": "Worker chờ bao lâu để một host công khai kết nối, xong bắt tay TLS hoặc trả lời đường health trước khi coi là lỗi.", "raise": "Host chậm ít bị báo hỏng hơn, nhưng host treo giữ lượt kiểm tra lâu hơn.", "lower": "Trả lời chậm bị tính là lỗi sớm hơn; đặt quá thấp thì host bận nhưng vẫn chạy sẽ bị báo hỏng.", "when": "Tăng nếu một host bị báo hỏng trong khi trình duyệt vẫn mở được; còn lại giữ mặc định.", "example": "Với mặc định 10, đường health trả lời sau 12 giây bị báo là yêu cầu lỗi."}}},
{"key": "cis.ops.external_check_targets", "app": "cis", "area": "ops", "label": "External checks: public hosts the worker checks", "description": "The public hosts the CIS worker checks from outside (job kind ops_external_check), a list of objects: id (lower-case letters, digits and hyphens, at most 60), app (cis, tripplanner, booking, crm or shared), host (a public host name), mode (health: DNS, TLS and one GET of path; tls: DNS and TLS only), and for mode health: path (starting with /) and expect (the HTTP statuses that count as up; a sign-in redirect is an answer). A target with a bad field is skipped and named in the job's result. Public host names only, never a secret or an internal address. The default equals the root repo's tools/ops/external_checks.json (the GitHub workflow's list); keep both in step when a public host is added.", "value_type": "json", "unit": null, "min_value": null, "max_value": null, "allowed_values": null, "default_value": [{"id": "cis-api", "app": "cis", "host": "api-cis.lumiguides.it.com", "mode": "health", "path": "/health", "expect": [200]}, {"id": "cis-admin", "app": "cis", "host": "aa-cis.lumiguides.it.com", "mode": "health", "path": "/", "expect": [200, 301, 302, 307, 308]}, {"id": "booking-api", "app": "booking", "host": "api-booking.lumiguides.it.com", "mode": "health", "path": "/booking/health", "expect": [200]}, {"id": "booking-admin", "app": "booking", "host": "booking.lumiguides.it.com", "mode": "health", "path": "/", "expect": [200, 301, 302, 307, 308]}, {"id": "crm-api", "app": "crm", "host": "partner-dev.lumiguides.it.com", "mode": "health", "path": "/crm/health", "expect": [200]}, {"id": "crm-portal", "app": "crm", "host": "portal.lumiguides.it.com", "mode": "health", "path": "/", "expect": [200, 301, 302, 307, 308]}, {"id": "tripplanner-web", "app": "tripplanner", "host": "tripplanner.lumiguides.it.com", "mode": "health", "path": "/", "expect": [200, 301, 302, 307, 308]}, {"id": "staff-sign-in", "app": "shared", "host": "staff-auth.lumiguides.it.com", "mode": "tls"}], "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The list of public addresses (APIs, admin sites, sign-in page) the worker checks from outside every few minutes.", "raise": "Adding a host: its DNS, certificate and health path show on the status page and raise an alert when they fail.", "lower": "Removing a host: it is no longer checked by the worker; its old rows stay until they leave the history window.", "when": "Add a host when a new public site or API goes live; remove one when it is retired.", "example": "With the default list, the CIS API's /health must answer 200 and the admin site may answer 200 or a sign-in redirect."}, "vi": {"what": "Danh sách địa chỉ công khai (API, trang quản trị, trang đăng nhập) worker kiểm tra từ bên ngoài sau mỗi vài phút.", "raise": "Thêm host: DNS, chứng chỉ và đường health của nó hiện trên trang trạng thái và báo động khi lỗi.", "lower": "Bỏ host: worker không kiểm tra nó nữa; các dòng cũ còn lại tới khi ra khỏi cửa sổ lịch sử.", "when": "Thêm host khi một trang hay API công khai mới chạy; bỏ khi nó ngừng dùng.", "example": "Với danh sách mặc định, /health của API CIS phải trả 200 và trang quản trị được trả 200 hoặc chuyển hướng sang đăng nhập."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('493', now(), 'AA-1142: external checks on the CIS worker: sources, interval, time limit, targets (settings)')
ON CONFLICT (version) DO NOTHING;

COMMIT;
